<div class="topline"><span>YOUR PERSONAL LIBRARY</span><span>Certificates, CVs, and university files.</span></div>
<header class="page-header"><div><h1>Keep the important things close.</h1><p class="muted">Organize your documents on this laptop.</p></div><a class="btn secondary" href="/settings/encrypted">Encrypted backup</a></header>
<?php require ROOT.'/app/Core/views/notices.php'; ?>
<nav class="tabs" aria-label="Document views"><a href="/documents" <?= !$trash ? 'class="selected" aria-current="page"' : '' ?>>My documents</a><a href="/documents?trash=1" <?= $trash ? 'class="selected" aria-current="page"' : '' ?>>Trash</a></nav>
<section class="card"><div class="section-heading"><h2><?= $trash ? 'Trash' : 'Your documents' ?></h2><span class="muted"><?= count($rows) ?> files</span></div>
<form class="inline" method="get" action="/documents"><?php if ($trash): ?><input type="hidden" name="trash" value="1"><?php endif; ?><label class="grow">Search<input name="q" value="<?= e($search) ?>" maxlength="200" placeholder="Title, notes, or filename"></label><label>Category<select name="category"><option value="">All categories</option><?php foreach (DocumentService::CATEGORIES as $c): ?><option value="<?= e($c) ?>" <?= $category===$c ? 'selected' : '' ?>><?= e($c) ?></option><?php endforeach; ?></select></label><button class="secondary">Search</button></form>
<?php if (!$rows): ?><div class="empty"><h3>No data yet.</h3><p><?= $trash ? 'Documents moved to Trash will appear here.' : 'Upload a certificate, CV, or study document below to start your library.' ?></p></div><?php else: foreach ($rows as $row): ?><article class="lesson-entry"><div class="section-heading"><div><h3><?= e($row['title']) ?></h3><small><?= e($row['category']) ?> · <?= e(number_format($row['bytes']/1024,1)) ?> KiB · <?= e(substr($row['created_at'],0,10)) ?></small><small><?= e($row['original_name']) ?></small></div><a class="btn secondary" hx-boost="false" href="/documents/<?= e($row['id']) ?>/download">Download</a></div><p><?= nl2br(e($row['notes'])) ?></p>
<?php if ($trash): ?><form method="post" action="/documents/<?= e($row['id']) ?>/restore"><?= csrf_field() ?><button class="secondary">Restore document</button></form><?php else: ?><details><summary>Edit details</summary><form class="stack" method="post" action="/documents/<?= e($row['id']) ?>/update"><?= csrf_field() ?><label>Title<input name="title" maxlength="200" value="<?= e($row['title']) ?>" required></label><label>Category<select name="category"><?php foreach (DocumentService::CATEGORIES as $c): ?><option value="<?= e($c) ?>" <?= $row['category']===$c ? 'selected' : '' ?>><?= e($c) ?></option><?php endforeach; ?></select></label><label>Notes<textarea name="notes" rows="2" maxlength="3000"><?= e($row['notes']) ?></textarea></label><button class="secondary">Save details</button></form></details><form method="post" action="/documents/<?= e($row['id']) ?>/trash"><?= csrf_field() ?><button class="quiet">Move to Trash</button></form><?php endif; ?></article><?php endforeach; endif; ?></section>
<?php if (!$trash): ?><section class="card" id="add-document"><h2>Add a document</h2><form class="form-grid" method="post" action="/documents/upload" enctype="multipart/form-data" hx-boost="false"><?= csrf_field() ?><label>Title<input name="title" maxlength="200" required placeholder="Document title"></label><label>Category<select name="category"><?php foreach (DocumentService::CATEGORIES as $c): ?><option><?= e($c) ?></option><?php endforeach; ?></select></label><label class="full">File<input type="file" name="document" accept=".pdf,.docx,.xlsx,.pptx,.txt,.csv,.png,.jpg,.jpeg,.webp" required></label><label class="full">Notes (optional)<textarea name="notes" rows="2" maxlength="3000"></textarea></label><p class="footnote full">Up to 25 MiB per file. Files are stored outside the public website folder. Moving a file to Trash keeps it available for recovery.</p><div class="full"><button>Save document</button></div></form></section><?php endif; ?>
